def compute(vars):
    euro_impact = vars["v1"]
    total_impact = vars["v2"]
    if total_impact == 0:
        return None
    value = euro_impact / total_impact * 100
    return {
        "value": value,
        "trace": {
            "euro_impact": euro_impact,
            "total_impact": total_impact,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
